//-----------------------------------------------------------------------------
// Set 16x16 sprite mode and load every sprite pattern into VRAM.
// Must run after VDP_SetMode + VDP_ClearVRAM (ClearVRAM wipes the pattern table).
void init_sprites(void)
{
    VDP_SetSpriteFlag(VDP_SPRITE_SIZE_16);

    // Gorgon fighters/bombers/bandits: pattern index p -> 8x8 index p*4, 4 units.
    VDP_LoadSpritePattern(sprite_figther1,      0,  4);
    VDP_LoadSpritePattern(sprite_figther2,      4,  4);
    VDP_LoadSpritePattern(sprite_figther1_flip, 8,  4);
    VDP_LoadSpritePattern(sprite_figther2_flip, 12, 4);
    VDP_LoadSpritePattern(sprite_bomber1,       16, 4);
    VDP_LoadSpritePattern(sprite_bomber2,       20, 4);
    VDP_LoadSpritePattern(sprite_bomber1_flip,  24, 4);
    VDP_LoadSpritePattern(sprite_bomber2_flip,  28, 4);
    VDP_LoadSpritePattern(sprite_bandit1,       32, 4);
    VDP_LoadSpritePattern(sprite_bandit2,       36, 4);
    VDP_LoadSpritePattern(sprite_bandit1_flip,  40, 4);
    VDP_LoadSpritePattern(sprite_bandit2_flip,  44, 4);

    // Torpedoes (12-14), explosion frames (15-24) and deathray slots (25-28):
    // 17 16x16 patterns = 544 bytes at 8x8 index 48 (= 16x16 index 12).
    VDP_WriteVRAM_16K(sprites, g_SpritePatternLow + 384, 544);
}


//-----------------------------------------------------------------------------
// Write the 17-attribute sprite table (68 bytes) to VRAM.
void sprites_flush(void)
{
    VDP_WriteVRAM_16K((const u8*)sprites_attributes, g_SpriteAttributeLow, 68);
}


//-----------------------------------------------------------------------------
// Set sprite magnification (R#1 bit 0). x2 magnification is global, so the
// bandit big explosion magnifies every sprite on screen (legacy behaviour).
// Always keeps the 16x16 size bit set. Matches the legacy ubox_wvdp(1, 0xE2)
// (off) and ubox_wvdp(1, 0xE3) (on).
void sprites_set_magnification(bool on)
{
    VDP_SetSpriteFlag(VDP_SPRITE_SIZE_16 | (on ? VDP_SPRITE_SCALE_2 : VDP_SPRITE_SCALE_1));
}


void sprites_disable_deathray(void)
{
    sprites_attributes[10].Color = 0;
    sprites_attributes[11].Color = 0;
    sprites_attributes[12].Color = 0;
    sprites_attributes[13].Color = 0;
    sprites_attributes[14].Color = 0;
}


void sprites_update_deathray(u8 x, u8 frame)
{
    sprites_attributes[10].X = x;
    sprites_attributes[11].X = x;
    sprites_attributes[12].X = x;
    sprites_attributes[13].X = x;
    sprites_attributes[14].X = x;

    sprites_attributes[10].Pattern = 25*4 + frame*4;
    sprites_attributes[11].Pattern = 25*4 + frame*4;
    sprites_attributes[12].Pattern = 25*4 + frame*4;
    sprites_attributes[13].Pattern = 25*4 + frame*4;
    sprites_attributes[14].Pattern = 25*4 + frame*4;

    sprites_attributes[10].Color = 8 + frame;
    sprites_attributes[11].Color = 8 + frame;
    sprites_attributes[12].Color = 8 + frame;
    sprites_attributes[13].Color = 8 + frame;
    sprites_attributes[14].Color = 8 + frame;
}
